import{_ as r,o as t,c as s,am as a}from"./chunks/framework.yj4qiWdr.js";const u=JSON.parse('{"title":"OSINT","description":"Outils et ressources de recherche en sources ouvertes, en français.","frontmatter":{"title":"OSINT","description":"Outils et ressources de recherche en sources ouvertes, en français.","aside":false,"prev":false,"next":false},"headers":[],"relativePath":"osint/index.md","filePath":"osint/index.md"}'),o={name:"osint/index.md"};function i(n,e,l,h,c,g){return t(),s("div",null,e[0]||(e[0]=[a('<h1 id="osint" tabindex="-1">OSINT <a class="header-anchor" href="#osint" aria-label="Permalink to &quot;OSINT&quot;">​</a></h1><p>Recherche en sources ouvertes : outils, moteurs de recherche et méthodes d&#39;investigation.</p><p><strong><a href="./cheatsheet">Cheatsheet OSINT</a></strong> - Commandes prêtes à adapter, avec une explication en français pour chaque usage.</p><h2 id="bibliotheque-osint" tabindex="-1">Bibliothèque OSINT <a class="header-anchor" href="#bibliotheque-osint" aria-label="Permalink to &quot;Bibliothèque OSINT&quot;">​</a></h2><ul><li><strong>Awesome OSINT</strong> - Catalogue de ressources classées par domaine. <a href="https://github.com/jivoi/awesome-osint" target="_blank" rel="noreferrer">https://github.com/jivoi/awesome-osint</a></li><li><strong>OSINT Framework</strong> - Répertoire d&#39;outils organisé par type de recherche. <a href="https://osintframework.com/" target="_blank" rel="noreferrer">https://osintframework.com/</a></li><li><strong>Bellingcat Toolkit</strong> - Outils pour rechercher, recouper et vérifier des informations. <a href="https://bellingcat.gitbook.io/toolkit" target="_blank" rel="noreferrer">https://bellingcat.gitbook.io/toolkit</a></li></ul><h2 id="pseudonymes-et-comptes" tabindex="-1">Pseudonymes et comptes <a class="header-anchor" href="#pseudonymes-et-comptes" aria-label="Permalink to &quot;Pseudonymes et comptes&quot;">​</a></h2><ul><li><strong>Sherlock</strong> - Recherche de profils publics associés à un pseudonyme. <a href="https://github.com/sherlock-project/sherlock" target="_blank" rel="noreferrer">https://github.com/sherlock-project/sherlock</a></li><li><strong>Maigret</strong> - Recherche de comptes à partir d&#39;un identifiant et génération de rapports. <a href="https://github.com/soxoj/maigret" target="_blank" rel="noreferrer">https://github.com/soxoj/maigret</a></li><li><strong>Holehe</strong> - Vérifie les traces d&#39;inscription associées à une adresse e-mail. <a href="https://github.com/megadose/holehe" target="_blank" rel="noreferrer">https://github.com/megadose/holehe</a></li><li><strong>Have I Been Pwned</strong> - Recherche d&#39;exposition d&#39;adresses e-mail dans des incidents connus. <a href="https://haveibeenpwned.com/" target="_blank" rel="noreferrer">https://haveibeenpwned.com/</a></li></ul><h2 id="recherche-web" tabindex="-1">Recherche Web <a class="header-anchor" href="#recherche-web" aria-label="Permalink to &quot;Recherche Web&quot;">​</a></h2><ul><li><strong>Google</strong> - Recherche générale avec opérateurs avancés. <a href="https://www.google.com/" target="_blank" rel="noreferrer">https://www.google.com/</a></li><li><strong>Bing</strong> - Moteur de recherche complémentaire pour recouper des résultats. <a href="https://www.bing.com/" target="_blank" rel="noreferrer">https://www.bing.com/</a></li><li><strong>Brave Search</strong> - Moteur indépendant pour diversifier les résultats. <a href="https://search.brave.com/" target="_blank" rel="noreferrer">https://search.brave.com/</a></li><li><strong>Wayback Machine</strong> - Consultation de versions archivées de pages Web. <a href="https://web.archive.org/" target="_blank" rel="noreferrer">https://web.archive.org/</a></li></ul><h2 id="domaines-et-infrastructures" tabindex="-1">Domaines et infrastructures <a class="header-anchor" href="#domaines-et-infrastructures" aria-label="Permalink to &quot;Domaines et infrastructures&quot;">​</a></h2><ul><li><strong>theHarvester</strong> - Collecte passive de domaines, sous-domaines et adresses publiques. <a href="https://github.com/laramies/theHarvester" target="_blank" rel="noreferrer">https://github.com/laramies/theHarvester</a></li><li><strong>crt.sh</strong> - Recherche de noms de domaine présents dans les certificats publics. <a href="https://crt.sh/" target="_blank" rel="noreferrer">https://crt.sh/</a></li><li><strong>Shodan</strong> - Recherche de services exposés sur Internet. <a href="https://www.shodan.io/" target="_blank" rel="noreferrer">https://www.shodan.io/</a></li><li><strong>Censys</strong> - Recherche d&#39;hôtes et de certificats Internet. <a href="https://search.censys.io/" target="_blank" rel="noreferrer">https://search.censys.io/</a></li><li><strong>SecurityTrails</strong> - Recherche DNS et historique d&#39;infrastructures. <a href="https://securitytrails.com/dns-trails" target="_blank" rel="noreferrer">https://securitytrails.com/dns-trails</a></li><li><strong>VirusTotal</strong> - Recherche contextuelle sur des URL, domaines, IP et fichiers. <a href="https://www.virustotal.com/" target="_blank" rel="noreferrer">https://www.virustotal.com/</a></li></ul><h2 id="images-et-geolocalisation" tabindex="-1">Images et géolocalisation <a class="header-anchor" href="#images-et-geolocalisation" aria-label="Permalink to &quot;Images et géolocalisation&quot;">​</a></h2><ul><li><strong>Google Lens</strong> - Recherche inversée et analyse visuelle d&#39;images. <a href="https://lens.google.com/" target="_blank" rel="noreferrer">https://lens.google.com/</a></li><li><strong>TinEye</strong> - Recherche des occurrences publiques d&#39;une image. <a href="https://tineye.com/" target="_blank" rel="noreferrer">https://tineye.com/</a></li><li><strong>Google Earth</strong> - Consultation de vues géographiques et d&#39;images satellites. <a href="https://www.google.com/earth/" target="_blank" rel="noreferrer">https://www.google.com/earth/</a></li><li><strong>ExifTool</strong> - Lecture des métadonnées de photos et de documents. <a href="https://exiftool.org/" target="_blank" rel="noreferrer">https://exiftool.org/</a></li></ul><h2 id="entreprises-et-organisations" tabindex="-1">Entreprises et organisations <a class="header-anchor" href="#entreprises-et-organisations" aria-label="Permalink to &quot;Entreprises et organisations&quot;">​</a></h2><ul><li><strong>OpenCorporates</strong> - Recherche de sociétés et d&#39;informations de registre. <a href="https://opencorporates.com/" target="_blank" rel="noreferrer">https://opencorporates.com/</a></li><li><strong>Annuaire des entreprises</strong> - Informations publiques sur les entreprises françaises. <a href="https://annuaire-entreprises.data.gouv.fr/" target="_blank" rel="noreferrer">https://annuaire-entreprises.data.gouv.fr/</a></li></ul><h2 id="analyse-et-verification" tabindex="-1">Analyse et vérification <a class="header-anchor" href="#analyse-et-verification" aria-label="Permalink to &quot;Analyse et vérification&quot;">​</a></h2><ul><li><strong>CyberChef</strong> - Décodage, conversion et analyse de chaînes et de fichiers. <a href="https://gchq.github.io/CyberChef/" target="_blank" rel="noreferrer">https://gchq.github.io/CyberChef/</a></li><li><strong>MITRE ATT&amp;CK</strong> - Base de connaissances des techniques adverses. <a href="https://attack.mitre.org/" target="_blank" rel="noreferrer">https://attack.mitre.org/</a></li><li><strong>MISP</strong> - Partage et organisation d&#39;indicateurs de menace. <a href="https://www.misp-project.org/" target="_blank" rel="noreferrer">https://www.misp-project.org/</a></li></ul><h2 id="methode" tabindex="-1">Méthode <a class="header-anchor" href="#methode" aria-label="Permalink to &quot;Méthode&quot;">​</a></h2><ol><li><strong>Définir</strong> la question à résoudre et le périmètre.</li><li><strong>Collecter</strong> les informations publiques et enregistrer les URL.</li><li><strong>Recouper</strong> les résultats avant d&#39;associer deux comptes ou identités.</li><li><strong>Conserver</strong> la date, la source, le contexte et les limites de chaque observation.</li></ol><p>Les correspondances de pseudonymes, d&#39;e-mails ou d&#39;images sont des indices, pas des preuves d&#39;identité.</p><p><strong><a href="./cheatsheet">Ouvrir la cheatsheet OSINT</a></strong></p>',21)]))}const p=r(o,[["render",i]]);export{u as __pageData,p as default};
